    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="card" aria-labelledby="support-title">
        <p class="eyebrow">Support</p>
        <h1 id="support-title">Contact our support team</h1>
        <p class="lede">
          Send us your details and we&apos;ll get back to you as soon as we can.
        </p>

        <form id="contact-form" novalidate>
          <div class="form-field">
            <label for="full-name">
              Full name <span class="required" aria-hidden="true">*</span>
            </label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            />
            <p class="field-error" id="full-name-error" hidden>
              Please enter your full name.
            </p>
          </div>

          <div class="form-field">
            <label for="email-address">
              Email address <span class="required" aria-hidden="true">*</span>
            </label>
            <input
              id="email-address"
              name="email"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-describedby="email-address-error"
            />
            <p class="field-error" id="email-address-error" hidden>
              Please enter a valid email address.
            </p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number</label>
            <input
              id="phone-number"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-number-help phone-number-error"
            />
            <p class="field-help" id="phone-number-help">
              Optional. Use a format like +1 555 123 4567 or 555-123-4567.
            </p>
            <p class="field-error" id="phone-number-error" hidden>
              Enter a phone number in the requested format, or leave this field empty.
            </p>
          </div>

          <div class="actions">
            <button type="submit">Send message</button>
          </div>

          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("contact-form");
      const status = document.getElementById("form-status");
      const fields = [
        {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate(value) {
            return value.trim().length > 0;
          },
        },
        {
          input: document.getElementById("email-address"),
          error: document.getElementById("email-address-error"),
          validate(value) {
            return value.trim().length > 0 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
          },
        },
        {
          input: document.getElementById("phone-number"),
          error: document.getElementById("phone-number-error"),
          validate(value) {
            if (!value.trim()) {
              return true;
            }

            return /^\+?\d[\d\s().-]{7,}$/.test(value.trim());
          },
        },
      ];

      function setFieldState(field, isValid) {
        field.input.setAttribute("aria-invalid", String(!isValid));
        field.error.hidden = isValid;
      }

